export function t(k, vars: Bag = {}) {
  let v = STR[LANG][k] ?? STR.en[k] ?? k;
  if (typeof v === 'function') v = v(vars.n ?? 0, vars);
  return v.replace(/\{(\w+)\}/g, (_, x) => vars[x] ?? '');
}

